def set_run(run, size=14, bold=False):
    run.font.name = "Times New Roman"
    run._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    run.font.size = Pt(size)
    run.bold = bold
    run.italic = False
    run.underline = False
    run.font.color.rgb = RGBColor(0, 0, 0)


def P(doc, text, *, bold=False, center=False, right=False, indent=True, size=14, before=0, after=0, break_before=False, single=False):
    p = doc.add_paragraph()
    pf = p.paragraph_format
    pf.line_spacing_rule = WD_LINE_SPACING.SINGLE if single else WD_LINE_SPACING.ONE_POINT_FIVE
    pf.space_before = Pt(before)
    pf.space_after = Pt(after)
    pf.first_line_indent = Pt(35.45) if indent else Cm(0)
    if center:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    elif right:
        p.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    else:
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    if break_before:
        p.paragraph_format.page_break_before = True
    run = p.add_run(text)
    set_run(run, size, bold)
    return p


def style_heading(doc, name):
    st = doc.styles[name]
    st.font.name = "Times New Roman"
    st.font.size = Pt(14)
    st.font.bold = True
    st.font.italic = False
    st.font.color.rgb = RGBColor(0, 0, 0)
    st.font.underline = False
    rpr = st.element.get_or_add_rPr()
    rfonts = rpr.find(qn("w:rFonts"))
    if rfonts is None:
        rfonts = OxmlElement("w:rFonts")
        rpr.append(rfonts)
    for attr in ("w:ascii", "w:hAnsi", "w:cs", "w:eastAsia"):
        rfonts.set(qn(attr), "Times New Roman")


def heading(doc, text, level):
    p = doc.add_paragraph(text, style="Heading 1" if level == 1 else "Heading 2")
    pf = p.paragraph_format
    pf.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    pf.first_line_indent = Pt(35.45)
    pf.page_break_before = level == 1
    if level == 1:
        pf.space_before = Pt(0)
        pf.space_after = Pt(12)
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    else:
        pf.space_before = Pt(12)
        pf.space_after = Pt(6)
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    for run in p.runs:
        set_run(run, 14, True)
    return p


def chapter(doc, text):
    return heading(doc, text, 1)


def sub(doc, text):
    return heading(doc, text, 2)


def set_cell(cell, text, bold=False, center=False, header=False):
    cell.text = ""
    p = cell.paragraphs[0]
    pf = p.paragraph_format
    pf.first_line_indent = Cm(0)
    pf.line_spacing = 1.0
    pf.space_before = Pt(0)
    pf.space_after = Pt(0)
    pPr = p._p.get_or_add_pPr()
    pPr.append(OxmlElement("w:keepLines"))
    if center or header:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run(str(text))
    set_run(run, 10, bold or header)
    tc = cell._tc
    tcPr = tc.get_or_add_tcPr()
    tcMar = OxmlElement("w:tcMar")
    for edge, val in (("top", "40"), ("bottom", "40"), ("left", "60"), ("right", "60")):
        node = OxmlElement(f"w:{edge}")
        node.set(qn("w:w"), val)
        node.set(qn("w:type"), "dxa")
        tcMar.append(node)
    tcPr.append(tcMar)


def table(doc, number, title, headers, rows, widths=None):
    P(doc, f"Таблица {number}", right=True, indent=False, before=6, after=0, single=True)
    P(doc, title, bold=True, center=True, indent=False, before=0, after=6, single=True)
    tbl = doc.add_table(rows=1 + len(rows), cols=len(headers))
    tbl.style = "Table Grid"
    tbl.alignment = WD_TABLE_ALIGNMENT.CENTER
    tbl.autofit = True
    for i, h in enumerate(headers):
        set_cell(tbl.rows[0].cells[i], h, header=True)
    for r, row in enumerate(rows):
        for c, value in enumerate(row):
            set_cell(tbl.rows[r + 1].cells[c], value, center=(c == 0 and str(value).isdigit()))
    if widths:
        for row in tbl.rows:
            for i, w in enumerate(widths):
                row.cells[i].width = Cm(w)
    return tbl


def footer(section):
    footer = section.footer
    footer.is_linked_to_previous = False
    p = footer.paragraphs[0]
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)
    run = p.add_run()
    set_run(run, 12)
    begin = OxmlElement("w:fldChar")
    begin.set(qn("w:fldCharType"), "begin")
    instr = OxmlElement("w:instrText")
    instr.set(qn("xml:space"), "preserve")
    instr.text = " PAGE "
    end = OxmlElement("w:fldChar")
    end.set(qn("w:fldCharType"), "end")
    run._r.append(begin)
    run._r.append(instr)
    run._r.append(end)


